const body = $json.body || {};
const first_name = String(body.first_name || '').trim();
const last_name = String(body.last_name || '').trim();
const technologies = String(body.technologies || '').trim();
const description = String(body.description || '').trim();

const errors = [];
if (!first_name) errors.push('first_name is required');
else if (first_name.length > 50) errors.push('first_name exceeds the maximum allowed length of 50 characters');
if (!last_name) errors.push('last_name is required');
else if (last_name.length > 50) errors.push('last_name exceeds the maximum allowed length of 50 characters');
if (!technologies) errors.push('technologies is required');
else if (technologies.length > 1000) errors.push('technologies exceeds the maximum allowed length of 1000 characters');
if (!description) errors.push('description is required');
else if (description.length > 5000) errors.push('description exceeds the maximum allowed length of 5000 characters');

const out = {
  first_name, last_name, technologies, description,
  validation_ok: errors.length === 0,
  validation_error: errors.length ? errors[0] : null,
};
const result = { json: out };
if ($input.item.binary) result.binary = $input.item.binary;
return result;

const j = $json;
// If text validation already failed, keep that error and stop here.
if (j.validation_ok === false) { return { json: j }; }

const binaries = $input.item.binary || {};
const keys = Object.keys(binaries);
let key = null; let meta = null;
for (const k of keys) {
  const b = binaries[k];
  const mt = String(b.mimeType || '').toLowerCase();
  const ext = String(b.fileExtension || '').toLowerCase();
  const nameIsPdf = String(b.fileName || '').toLowerCase().endsWith('.pdf');
  if (mt === 'application/pdf' || ext === 'pdf' || nameIsPdf) { key = k; meta = b; break; }
}
if (key === null) { key = keys.length ? keys[0] : null; meta = key !== null ? binaries[key] : null; }

let buf = null;
try { if (key !== null) { buf = await this.helpers.getBinaryDataBuffer(0, key); } } catch (e) { buf = null; }

const MAX_BYTES = 5 * 1024 * 1024;
const errors = [];
if (key === null || !meta) {
  errors.push('A valid PDF CV file is required');
} else if (!buf || buf.length === 0) {
  errors.push('A valid PDF CV file is required');
} else if (buf.length > MAX_BYTES) {
  errors.push('CV file exceeds the maximum allowed size of 5 MB');
} else {
  const mt = String(meta.mimeType || '').toLowerCase();
  const ext = String(meta.fileExtension || '').toLowerCase();
  const nameLower = String(meta.fileName || '').toLowerCase();
  const mimeOk = meta.mimeType ? mt === 'application/pdf' : true;
  const extOk = ext === 'pdf' || nameLower.endsWith('.pdf');
  const magicOk = buf.subarray(0, 5).toString('latin1').startsWith('%PDF');
  if (!magicOk || !extOk || !mimeOk) errors.push('A valid PDF CV file is required');
}

// Sanitize the original filename (strip path traversal); never used in the storage path.
let cleanName = key !== null ? String(meta.fileName || 'cv.pdf') : 'cv.pdf';
cleanName = cleanName.replace(/[\\/]/g, '_').replace(/\.\.+/g, '_').replace(/[^a-zA-Z0-9._-]/g, '_');
if (!cleanName.toLowerCase().endsWith('.pdf')) cleanName = cleanName + '.pdf';

// Generated safe identifier drives the storage path, not the user filename.
const safeId = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const objectPath = 'applications/' + safeId + '.pdf';

const out = {
  first_name: j.first_name, last_name: j.last_name,
  technologies: j.technologies, description: j.description,
  cv_filename: cleanName,
  cv_object_path: objectPath,
  validation_ok: errors.length === 0,
  validation_error: errors.length ? errors[0] : null,
};
const result = { json: out };
if (errors.length === 0 && key !== null && buf) { result.binary = { data: meta }; }
return result;

const text = String($json.text || '');
const MAX_CHARS = 30000;
const ok = text.length <= MAX_CHARS;
const result = { json: Object.assign({}, $json, {
  cv_text_ok: ok,
  cv_text_error: ok ? null : 'Extracted CV content exceeds the maximum allowed length',
}) };
// Carry the original PDF binary forward so 'Save CV' still receives binary.data.
if ($input.item.binary) result.binary = $input.item.binary;
return result;

