const o = $json.output || {};
const rubric = (o.rubric && typeof o.rubric === 'object') ? o.rubric : {};
return { json: {
  raw_score: o.score,
  recommendation: o.recommendation,
  strengths: Array.isArray(o.strengths) ? o.strengths : null,
  risks: Array.isArray(o.risks) ? o.risks : null,
  reasoning: o.reasoning,
  rubric,
} };

const j = $json;
const maxes = { rest_api: 20, llm_experience: 20, agentic_ai_mcp: 15, education: 10, automation_tools: 10, apify: 5, openai_anthropic_api: 5, lovable_cursor: 5, learning_research: 10 };
const isInt = (n) => Number.isInteger(n);
const rubric = (j.rubric && typeof j.rubric === 'object') ? j.rubric : {};
const score = Number(j.raw_score);
const errors = [];

if (!isInt(score) || score < 0 || score > 100) errors.push('score out of range');
if (!Array.isArray(j.strengths)) errors.push('strengths must be an array');
if (!Array.isArray(j.risks)) errors.push('risks must be an array');
if (typeof j.reasoning !== 'string' || !j.reasoning) errors.push('reasoning must be a non-empty string');

let sum = 0;
const keys = Object.keys(maxes);
for (const k of keys) {
  const v = Number(rubric[k]);
  if (!isInt(v) || v < 0 || v > maxes[k]) errors.push(k + ' rubric value invalid (0-' + maxes[k] + ')');
  else sum += v;
}
if (isInt(score) && errors.filter((e) => e.indexOf('rubric value invalid') !== -1).length === 0 && sum !== score) {
  errors.push('rubric sum (' + sum + ') != score (' + score + ')');
}
if (Array.isArray(j.strengths) && j.strengths.length < 2) errors.push('need at least 2 strengths');

let recommendation;

if (isInt(score) && score >= 75) {
  recommendation = 'Evet';
} else if (isInt(score) && score >= 45) {
  recommendation = 'Belki';
} else if (isInt(score)) {
  recommendation = 'Hayır';
} else {
  recommendation = null;
}

return { json: {
  eval_ok: errors.length === 0,
  eval_error: errors.length ? errors.join('; ') : null,
  score,
  recommendation,
  strengths_json: JSON.stringify(Array.isArray(j.strengths) ? j.strengths : []),
  risks_json: JSON.stringify(Array.isArray(j.risks) ? j.risks : []),
  reasoning: String(j.reasoning || ''),
  evaluation_details: rubric,
} };
